import React, { useEffect, useState } from 'react';
import { ArrowRight, Sparkles, ChevronDown } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const Hero = () => {
  const [typedText, setTypedText] = useState('');
  const { settings } = useAuth();
  const fullText = 'We Build Digital Experiences';

  useEffect(() => {
    let index = 0;
    const timer = setInterval(() => {
      if (index <= fullText.length) {
        setTypedText(fullText.slice(0, index));
        index++;
      } else {
        clearInterval(timer);
      }
    }, 100);
    return () => clearInterval(timer);
  }, []);

  const siteTitle = settings.site_title || 'Project MUN';
  const titleParts = siteTitle.split(' ');

  return (
    <section id="home" className="relative min-h-screen flex items-center justify-center overflow-hidden geometric-bg">

      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        {/* Main Heading */}
        <h1 className="text-5xl sm:text-6xl md:text-7xl lg:text-8xl font-black mb-6 tracking-tight">
          <span className="text-white">{titleParts[0]}</span>
          <span className="gradient-text ml-4">{titleParts.slice(1).join(' ') || 'MUN'}</span>
        </h1>

        {/* Typed Tagline */}
        <div className="h-16 sm:h-20 flex items-center justify-center mb-8">
          <p className="text-xl sm:text-2xl md:text-4xl text-gray-300 font-light">
            {typedText}
            <span className="animate-pulse text-blue-400">|</span>
          </p>
        </div>

        {/* Description */}
        <p className="text-base sm:text-lg text-gray-400 max-w-2xl mx-auto mb-12 leading-relaxed px-4">
          We are a team of passionate developers crafting innovative web solutions 
          for modern businesses. From concept to deployment, we bring your vision to life.
        </p>

        {/* CTA Buttons */}
        <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
          <a
            href="#portfolio"
            className="group flex items-center gap-2 px-8 py-4 bg-blue-600 text-white font-semibold rounded-full hover:bg-blue-500 transition-all duration-300"
          >
            View Portfolio
            <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
          </a>
          <a
            href="#contact"
            className="flex items-center gap-2 px-8 py-4 border border-white/20 text-white font-semibold rounded-full hover:bg-white/10 transition-all duration-300"
          >
            Contact Us
          </a>
        </div>

        {/* Stats */}
        <div className="mt-20 grid grid-cols-3 gap-8 max-w-2xl mx-auto">
          {[
            { value: '10+', label: 'Projects Completed' },
            { value: '4', label: 'Team Members' },
            { value: '100%', label: 'Client Satisfaction' },
          ].map((stat, index) => (
            <div key={index} className="text-center">
              <div className="text-3xl sm:text-4xl font-bold gradient-text mb-1">{stat.value}</div>
              <div className="text-sm text-gray-400">{stat.label}</div>
            </div>
          ))}
        </div>
      </div>

    </section>
  );
};

export default Hero;
